import React, { useRef, useEffect } from 'react';

// Luminous glowing orb — like the burning sun app reference
// No edges at all, just pure light emanating from centre
export default function MeshSphere({ size = 340, speed = 0.4, distort = 0.5, hue1 = 200, hue2 = 220 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2;

    const draw = () => {
      t.current += 0.005 * speed;
      ctx.clearRect(0, 0, size, size);

      const pulse = 1 + Math.sin(t.current * 0.6) * 0.03;
      const drift = {
        x: Math.sin(t.current * 0.3) * size * 0.018,
        y: Math.cos(t.current * 0.25) * size * 0.014,
      };

      // Current hues — slowly shift
      const h1 = hue1 + Math.sin(t.current * 0.12) * 12;
      const h2 = hue2 + Math.cos(t.current * 0.09) * 10;

      // ── Layer 1: Massive outer corona ──────────────────────
      const corona = ctx.createRadialGradient(
        cx + drift.x, cy + drift.y, 0,
        cx + drift.x, cy + drift.y, size * 0.50 * pulse
      );
      corona.addColorStop(0,   `hsla(${h1 + 20}, 70%, 65%, 0.18)`);
      corona.addColorStop(0.4, `hsla(${h1},      65%, 55%, 0.12)`);
      corona.addColorStop(0.7, `hsla(${h2},      60%, 50%, 0.06)`);
      corona.addColorStop(1,   'transparent');
      ctx.fillStyle = corona;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 2: Main body — rich saturated glow ───────────
      const body = ctx.createRadialGradient(
        cx + drift.x * 0.5, cy + drift.y * 0.5, 0,
        cx, cy, size * 0.36 * pulse
      );
      body.addColorStop(0,    `hsla(${h1 + 30}, 72%, 72%, 0.92)`);
      body.addColorStop(0.22, `hsla(${h1 + 15}, 70%, 60%, 0.80)`);
      body.addColorStop(0.48, `hsla(${h1},      68%, 50%, 0.62)`);
      body.addColorStop(0.72, `hsla(${h2},      62%, 45%, 0.35)`);
      body.addColorStop(1,    'transparent');
      ctx.fillStyle = body;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 3: Secondary colour mass ─────────────────────
      const ox2 = -Math.sin(t.current * 0.22) * size * 0.06;
      const oy2 = -Math.cos(t.current * 0.18) * size * 0.05;
      const mass2 = ctx.createRadialGradient(
        cx + ox2, cy + oy2, 0,
        cx + ox2, cy + oy2, size * 0.28 * pulse
      );
      mass2.addColorStop(0,   `hsla(${h2 + 10}, 65%, 62%, 0.70)`);
      mass2.addColorStop(0.5, `hsla(${h2},      60%, 55%, 0.38)`);
      mass2.addColorStop(1,   'transparent');
      ctx.fillStyle = mass2;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 4: Bright hot centre ─────────────────────────
      const core = ctx.createRadialGradient(
        cx + drift.x * 0.3, cy + drift.y * 0.3, 0,
        cx, cy, size * 0.14 * pulse
      );
      core.addColorStop(0,    `hsla(${h1 + 50}, 80%, 92%, 0.85)`);
      core.addColorStop(0.4,  `hsla(${h1 + 35}, 75%, 78%, 0.45)`);
      core.addColorStop(0.8,  `hsla(${h1 + 20}, 68%, 65%, 0.12)`);
      core.addColorStop(1,    'transparent');
      ctx.fillStyle = core;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 5: Ring accent — like the GROW reference ─────
      const ringOuter = size * 0.40 * pulse;
      const ringInner = size * 0.22 * pulse;
      const ring = ctx.createRadialGradient(cx, cy, ringInner, cx, cy, ringOuter);
      ring.addColorStop(0,    `hsla(${h1 + 10}, 68%, 70%, 0.22)`);
      ring.addColorStop(0.35, `hsla(${h1},      70%, 58%, 0.40)`);
      ring.addColorStop(0.6,  `hsla(${h2},      65%, 52%, 0.32)`);
      ring.addColorStop(1,    'transparent');
      ctx.fillStyle = ring;
      ctx.fillRect(0, 0, size, size);

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort, hue1, hue2]);

  return <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />;
}
